namespace XPScript.Compiler;

internal static class NotesViewNavigationV2PostProcessor
{
    public static string Apply(string source)
    {
        ArgumentNullException.ThrowIfNull(source);

        source = ReplaceRequired(
            source,
            "    public XPScriptNotesViewNavigator CreateViewNav()\n    {\n        EnsureAlive();\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows());\n    }",
            "    public XPScriptNotesViewNavigator CreateViewNav()\n    {\n        EnsureAlive();\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows());\n    }\n\n    public XPScriptNotesViewNavigator CreateViewNavMaxLevel(object? maxLevelValue)\n    {\n        EnsureAlive();\n        var maxLevel = Math.Max(0, XPScriptRuntime.CInt(maxLevelValue));\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows().Where(row => row.Level <= maxLevel));\n    }\n\n    public XPScriptNotesViewNavigator CreateViewNavFromCategory(object? categoryValue)\n    {\n        EnsureAlive();\n        var category = XPScriptRuntime.CStr(categoryValue);\n        var rows = ReadRows();\n        var root = rows.FirstOrDefault(row => row.Type == XPScriptNotesViewEntryType.Category && row.GetColumnValues().Any(value => string.Equals(XPScriptRuntime.CStr(value), category, StringComparison.OrdinalIgnoreCase)));\n        if (root is null) return new XPScriptNotesViewNavigator(Session, this, Database, Array.Empty<XPScriptNotesViewRow>());\n        return new XPScriptNotesViewNavigator(Session, this, Database, rows.Where(row => ReferenceEquals(row, root) || IsDescendant(root, row)));\n    }\n\n    public XPScriptNotesViewNavigator CreateViewNavFrom(object? entryValue)\n    {\n        EnsureAlive();\n        var entry = RequireViewEntry(entryValue, \"CreateViewNavFrom\");\n        var root = entry.Row;\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows().Where(row => SameRow(root, row) || IsDescendant(root, row)));\n    }\n\n    public XPScriptNotesViewNavigator CreateViewNavFromChildren(object? entryValue)\n    {\n        EnsureAlive();\n        var root = RequireViewEntry(entryValue, \"CreateViewNavFromChildren\").Row;\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows().Where(row => IsDirectChild(root, row)));\n    }\n\n    public XPScriptNotesViewNavigator CreateViewNavFromDescendants(object? entryValue)\n    {\n        EnsureAlive();\n        var root = RequireViewEntry(entryValue, \"CreateViewNavFromDescendants\").Row;\n        return new XPScriptNotesViewNavigator(Session, this, Database, ReadRows().Where(row => IsDescendant(root, row)));\n    }\n\n    private static XPScriptNotesViewEntry RequireViewEntry(object? value, string member)\n    {\n        if (value is not XPScriptNotesViewEntry entry) throw new XPScriptRuntimeException(13, member + \" requires a NotesViewEntry.\");\n        entry.EnsureAliveForNavigation();\n        return entry;\n    }\n\n    internal static bool SameRow(XPScriptNotesViewRow left, XPScriptNotesViewRow right)\n        => ReferenceEquals(left, right) || (left.NoteId == right.NoteId && string.Equals(left.Position, right.Position, StringComparison.Ordinal));\n\n    internal static bool IsDescendant(XPScriptNotesViewRow parent, XPScriptNotesViewRow candidate)\n        => candidate.Level > parent.Level && candidate.Position.StartsWith(parent.Position + \".\", StringComparison.Ordinal);\n\n    internal static bool IsDirectChild(XPScriptNotesViewRow parent, XPScriptNotesViewRow candidate)\n        => candidate.Level == parent.Level + 1 && candidate.Position.StartsWith(parent.Position + \".\", StringComparison.Ordinal);",
            "view-v2-factories");

        source = ReplaceRequired(
            source,
            "    public int IndentLevel { get { EnsureAlive(); return Row.IndentLevel; } }",
            "    public int IndentLevel { get { EnsureAlive(); return Row.IndentLevel; } }\n    public int ColumnIndentLevel { get { EnsureAlive(); return Row.IndentLevel; } }\n    public int ChildCount { get { EnsureAlive(); return _view.ReadRows().Count(row => NotesViewNavigationV2PostProcessor.IsDirectChild(Row, row)); } }\n    public int DescendantCount { get { EnsureAlive(); return _view.ReadRows().Count(row => NotesViewNavigationV2PostProcessor.IsDescendant(Row, row)); } }\n    public int SiblingCount\n    {\n        get\n        {\n            EnsureAlive();\n            var parent = ParentPosition(Row.Position);\n            return _view.ReadRows().Count(row => row.Level == Row.Level && string.Equals(ParentPosition(row.Position), parent, StringComparison.Ordinal));\n        }\n    }\n    public bool IsConflict { get { EnsureAlive(); return false; } }\n    private static string ParentPosition(string position)\n    {\n        var index = position.LastIndexOf('.');\n        return index < 0 ? \"\" : position[..index];\n    }",
            "entry-v2-properties");

        source = ReplaceRequired(
            source,
            "    public int Count { get { EnsureAlive(); return _rows.Length; } }",
            "    public int Count { get { EnsureAlive(); return VisibleRows().Length; } }\n    private int _cacheSize;\n    private int _maxLevel = int.MaxValue;\n    public int CacheSize { get { EnsureAlive(); return _cacheSize; } set { EnsureAlive(); _cacheSize = Math.Max(0, value); } }\n    public int MaxLevel { get { EnsureAlive(); return _maxLevel == int.MaxValue ? 30 : _maxLevel; } set { EnsureAlive(); _maxLevel = value < 0 ? 0 : value; NormalizeCurrent(); } }",
            "navigator-v2-properties");

        source = ReplaceRequired(
            source,
            "    public XPScriptNotesViewEntry? GetPrevDocument() => FindDocument(_currentIndex < 0 ? _rows.Length - 1 : _currentIndex - 1, -1);",
            "    public XPScriptNotesViewEntry? GetPrevDocument() => FindDocument(_currentIndex < 0 ? _rows.Length - 1 : _currentIndex - 1, -1);\n    public XPScriptNotesViewEntry? GetNext(object? entryValue) => MoveRelative(entryValue, 1, null, \"GetNext\");\n    public XPScriptNotesViewEntry? GetPrev(object? entryValue) => MoveRelative(entryValue, -1, null, \"GetPrev\");\n    public XPScriptNotesViewEntry? GetNextDocument(object? entryValue) => MoveRelative(entryValue, 1, XPScriptNotesViewEntryType.Document, \"GetNextDocument\");\n    public XPScriptNotesViewEntry? GetPrevDocument(object? entryValue) => MoveRelative(entryValue, -1, XPScriptNotesViewEntryType.Document, \"GetPrevDocument\");\n    public XPScriptNotesViewEntry? GetNextCategory() => FindType(_currentIndex < 0 ? 0 : _currentIndex + 1, 1, XPScriptNotesViewEntryType.Category);\n    public XPScriptNotesViewEntry? GetPrevCategory() => FindType(_currentIndex < 0 ? _rows.Length - 1 : _currentIndex - 1, -1, XPScriptNotesViewEntryType.Category);\n    public XPScriptNotesViewEntry? GetNextCategory(object? entryValue) => MoveRelative(entryValue, 1, XPScriptNotesViewEntryType.Category, \"GetNextCategory\");\n    public XPScriptNotesViewEntry? GetPrevCategory(object? entryValue) => MoveRelative(entryValue, -1, XPScriptNotesViewEntryType.Category, \"GetPrevCategory\");\n    public XPScriptNotesViewEntry? GetChild() => GetChild(CurrentEntryValue());\n    public XPScriptNotesViewEntry? GetChild(object? entryValue)\n    {\n        var row = RequireEntryRow(entryValue, \"GetChild\");\n        var index = Array.FindIndex(_rows, candidate => NotesViewNavigationV2PostProcessor.IsDirectChild(row, candidate) && IsVisible(candidate));\n        return OpenAt(index, index >= 0);\n    }\n    public XPScriptNotesViewEntry? GetParent() => GetParent(CurrentEntryValue());\n    public XPScriptNotesViewEntry? GetParent(object? entryValue)\n    {\n        var row = RequireEntryRow(entryValue, \"GetParent\");\n        var parentPosition = ParentPosition(row.Position);\n        if (parentPosition.Length == 0) return null;\n        var index = Array.FindIndex(_rows, candidate => string.Equals(candidate.Position, parentPosition, StringComparison.Ordinal) && IsVisible(candidate));\n        return OpenAt(index, index >= 0);\n    }\n    public XPScriptNotesViewEntry? GetNextSibling() => GetNextSibling(CurrentEntryValue());\n    public XPScriptNotesViewEntry? GetNextSibling(object? entryValue) => FindSibling(entryValue, 1, \"GetNextSibling\");\n    public XPScriptNotesViewEntry? GetPrevSibling() => GetPrevSibling(CurrentEntryValue());\n    public XPScriptNotesViewEntry? GetPrevSibling(object? entryValue) => FindSibling(entryValue, -1, \"GetPrevSibling\");\n    public XPScriptNotesViewEntry? GetNth(object? indexValue)\n    {\n        EnsureAlive();\n        var visible = VisibleRows();\n        var oneBased = XPScriptRuntime.CInt(indexValue);\n        if (oneBased <= 0 || oneBased > visible.Length) return null;\n        var index = Array.IndexOf(_rows, visible[oneBased - 1]);\n        return OpenAt(index, true);\n    }\n    public XPScriptNotesViewEntry? GetPos(object? positionValue, object? separatorValue)\n    {\n        EnsureAlive();\n        var separator = XPScriptRuntime.CStr(separatorValue);\n        var position = XPScriptRuntime.CStr(positionValue);\n        if (separator.Length > 0 && separator != \".\") position = position.Replace(separator, \".\", StringComparison.Ordinal);\n        var index = Array.FindIndex(_rows, row => IsVisible(row) && string.Equals(row.Position, position, StringComparison.Ordinal));\n        return OpenAt(index, index >= 0);\n    }\n    public void GotoFirst() => MoveIfFound(() => GetFirst());\n    public void GotoLast() => MoveIfFound(() => GetLast());\n    public void GotoFirstDocument() => MoveIfFound(() => GetFirstDocument());\n    public void GotoLastDocument() => MoveIfFound(() => GetLastDocument());\n    public void GotoNext(object? entryValue) => MoveIfFound(() => GetNext(entryValue));\n    public void GotoPrev(object? entryValue) => MoveIfFound(() => GetPrev(entryValue));\n    public void GotoNextDocument(object? entryValue) => MoveIfFound(() => GetNextDocument(entryValue));\n    public void GotoPrevDocument(object? entryValue) => MoveIfFound(() => GetPrevDocument(entryValue));\n    public void GotoNextCategory(object? entryValue) => MoveIfFound(() => GetNextCategory(entryValue));\n    public void GotoPrevCategory(object? entryValue) => MoveIfFound(() => GetPrevCategory(entryValue));\n    public void GotoChild(object? entryValue) => MoveIfFound(() => GetChild(entryValue));\n    public void GotoParent(object? entryValue) => MoveIfFound(() => GetParent(entryValue));\n    public void GotoNextSibling(object? entryValue) => MoveIfFound(() => GetNextSibling(entryValue));\n    public void GotoPrevSibling(object? entryValue) => MoveIfFound(() => GetPrevSibling(entryValue));\n    public void GotoEntry(object? entryValue)\n    {\n        var row = RequireEntryRow(entryValue, \"GotoEntry\");\n        var index = Array.FindIndex(_rows, candidate => NotesViewNavigationV2PostProcessor.SameRow(row, candidate) && IsVisible(candidate));\n        if (index >= 0) _currentIndex = index;\n    }\n    public void GotoPos(object? positionValue, object? separatorValue) => MoveIfFound(() => GetPos(positionValue, separatorValue));",
            "navigator-v2-methods");

        source = ReplaceRequired(
            source,
            "    private XPScriptNotesViewEntry? FindDocument(int start, int step)",
            "    private XPScriptNotesViewRow[] VisibleRows() => _rows.Where(IsVisible).ToArray();\n    private bool IsVisible(XPScriptNotesViewRow row) => row.Level <= _maxLevel;\n    private void NormalizeCurrent() { if (_currentIndex >= 0 && (_currentIndex >= _rows.Length || !IsVisible(_rows[_currentIndex]))) _currentIndex = -1; }\n    private object? CurrentEntryValue() => _currentIndex >= 0 && _currentIndex < _rows.Length ? new XPScriptNotesViewEntry(Session, _view, Database, _rows[_currentIndex]) : null;\n    private XPScriptNotesViewRow RequireEntryRow(object? value, string member)\n    {\n        EnsureAlive();\n        if (value is not XPScriptNotesViewEntry entry) throw new XPScriptRuntimeException(13, member + \" requires a NotesViewEntry.\");\n        entry.EnsureAliveForNavigation();\n        return entry.Row;\n    }\n    private XPScriptNotesViewEntry? MoveRelative(object? entryValue, int step, XPScriptNotesViewEntryType? type, string member)\n    {\n        var row = RequireEntryRow(entryValue, member);\n        var index = Array.FindIndex(_rows, candidate => NotesViewNavigationV2PostProcessor.SameRow(row, candidate));\n        if (index < 0) return null;\n        for (var i = index + step; i >= 0 && i < _rows.Length; i += step)\n            if (IsVisible(_rows[i]) && (type is null || _rows[i].Type == type.Value)) return OpenAt(i, true);\n        return null;\n    }\n    private XPScriptNotesViewEntry? FindType(int start, int step, XPScriptNotesViewEntryType type)\n    {\n        EnsureAlive();\n        for (var i = start; i >= 0 && i < _rows.Length; i += step)\n            if (IsVisible(_rows[i]) && _rows[i].Type == type) return OpenAt(i, true);\n        return null;\n    }\n    private XPScriptNotesViewEntry? FindSibling(object? entryValue, int step, string member)\n    {\n        var row = RequireEntryRow(entryValue, member);\n        var parent = ParentPosition(row.Position);\n        var index = Array.FindIndex(_rows, candidate => NotesViewNavigationV2PostProcessor.SameRow(row, candidate));\n        if (index < 0) return null;\n        for (var i = index + step; i >= 0 && i < _rows.Length; i += step)\n        {\n            var candidate = _rows[i];\n            if (candidate.Level < row.Level) break;\n            if (candidate.Level == row.Level && string.Equals(ParentPosition(candidate.Position), parent, StringComparison.Ordinal) && IsVisible(candidate)) return OpenAt(i, true);\n        }\n        return null;\n    }\n    private static string ParentPosition(string position)\n    {\n        var index = position.LastIndexOf('.');\n        return index < 0 ? \"\" : position[..index];\n    }\n    private void MoveIfFound(Func<XPScriptNotesViewEntry?> action)\n    {\n        var previous = _currentIndex;\n        var entry = action();\n        if (entry is null) _currentIndex = previous; else entry.Recycle();\n    }\n    private XPScriptNotesViewEntry? FindDocument(int start, int step)",
            "navigator-v2-helpers");

        source = source.Replace("if (_rows[i].IsDocument) return OpenAt(i, true);", "if (IsVisible(_rows[i]) && _rows[i].IsDocument) return OpenAt(i, true);", StringComparison.Ordinal);
        source = source.Replace("public XPScriptNotesViewEntry? GetFirst() => OpenAt(_rows.Length == 0 ? -1 : 0, true);", "public XPScriptNotesViewEntry? GetFirst() => OpenVisible(0, 1);", StringComparison.Ordinal);
        source = source.Replace("public XPScriptNotesViewEntry? GetLast() => OpenAt(_rows.Length == 0 ? -1 : _rows.Length - 1, true);", "public XPScriptNotesViewEntry? GetLast() => OpenVisible(_rows.Length - 1, -1);", StringComparison.Ordinal);
        source = source.Replace("public XPScriptNotesViewEntry? GetNext() => OpenAt(_currentIndex < 0 ? 0 : _currentIndex + 1, true);", "public XPScriptNotesViewEntry? GetNext() => OpenVisible(_currentIndex < 0 ? 0 : _currentIndex + 1, 1);", StringComparison.Ordinal);
        source = source.Replace("public XPScriptNotesViewEntry? GetPrev() => OpenAt(_currentIndex < 0 ? _rows.Length - 1 : _currentIndex - 1, true);", "public XPScriptNotesViewEntry? GetPrev() => OpenVisible(_currentIndex < 0 ? _rows.Length - 1 : _currentIndex - 1, -1);", StringComparison.Ordinal);
        source = ReplaceRequired(source, "    private XPScriptNotesViewEntry? OpenAt(int index, bool move)", "    private XPScriptNotesViewEntry? OpenVisible(int start, int step)\n    {\n        EnsureAlive();\n        for (var i = start; i >= 0 && i < _rows.Length; i += step) if (IsVisible(_rows[i])) return OpenAt(i, true);\n        return null;\n    }\n    private XPScriptNotesViewEntry? OpenAt(int index, bool move)", "navigator-visible-open");

        return source;
    }

    private static string ReplaceRequired(string source, string oldValue, string newValue, string stage)
    {
        if (!source.Contains(oldValue, StringComparison.Ordinal))
            throw new CompilerException("Unable to apply NotesView navigation V2 (" + stage + ").");
        return source.Replace(oldValue, newValue, StringComparison.Ordinal);
    }
}
